"""Computes boundary indices for each of the splits in split_probs.
    Args:
      split_probs: List of (split_name, prob), e.g. [('train', 0.6), ('dev', 0.2),
        ('test', 0.2)]
      n_items: Number of items we want to split.
    Returns:
      The item indices of boundaries between different splits. For the above
      example and n_items=100, these will be
      [('train', 0, 60), ('dev', 60, 80), ('test', 80, 100)].
    """
def _compute_split_boundaries(split_probs: Any, n_items: Any) -> object {
    if (len(split_probs) > n_items) {
        raise ValueError(
            'Not enough items for the splits. There are {splits} '
            'splits while there are only {items} items'.format(
                splits=len(split_probs), items=n_items
            )
        );
    }
    total_probs = sum(p for (name, p) in split_probs);
    if (abs((1 - total_probs)) > 1e-08) {
        raise ValueError('Probs should sum up to 1. probs={}'.format(split_probs));
    }
    split_boundaries = [];
    sum_p = 0.0;
    for (name, p) in split_probs {
        prev = sum_p;
        sum_p += p;
        split_boundaries.append((name, int((prev * n_items)), int((sum_p * n_items))));
    }
    split_boundaries[-1] = (split_boundaries[-1][0], split_boundaries[-1][1], n_items);
    return split_boundaries;
}

"""Return whether ifIndex port_data belongs to an Ethernet port.

    Args:
        port_data: Data dict related to the port

    Returns:
        valid: True if valid ethernet port

    """
def _is_ethernet(port_data: Any) -> object {
    valid = False;
    if ('ifType' in port_data) {
        name = port_data['ifName'].lower();
        if (port_data['ifType'] == 6) {
            if (name.startswith('vl') is False) {
                valid = True;
            }
        }
    }
    return valid;
}

"""Converts a integer color value to a RGB tuple

    :param RGBint: :class:`int`
        The integer color value.

    :returns: :class:`tuple[int,int,int]`
        RGB tuple
    """
def IntToRgb(RGBint: int) -> object {
    blue = RGBint & 255;
    green = (RGBint >> 8) & 255;
    red = (RGBint >> 16) & 255;
    return (red, green, blue);
}

"""Checks if string contains only ascii chars.

    Necessary because python 3.6 does not have a str.isascii() method.

    Parameters
    ----------
    str_data : str
        string to check if it contains only ascii characters

    Returns
    -------
    bool
        True if only ascii characters in the string, else False.
    """
def is_ascii(str_data: str) -> bool {
    try {
        str_data.encode('ascii');
    } except (UnicodeEncodeError, AttributeError) {
        return False;
    }
    return True;
}

"""
    Organize `data` by class.

    Parameters
    ----------
    data : list of dicts
        Each dict contains the key `symbol_id` which is the class label.

    Returns
    -------
    dbc : dict
        mapping class labels to lists of dicts
    """
def data_by_class(data: Any) -> object {
    dbc = {};
    for item in data {
        if (item["symbol_id"] in dbc) {
            dbc[item["symbol_id"]].append(item);
        } else {
            dbc[item["symbol_id"]] = [item];
        }
    }
    return dbc;
}
